message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve an execution failure identified during an earlier execution step.",
      "source_description": "An observed tool execution failure or error result.",
      "target_description": "A subsequent agent tool call intended to resolve or work around the failure."
    },
    {
      "name": "USES_OBSERVED_CONTENT_AS_EVIDENCE_FOR_CLASSIFICATION",
      "definition": "The agent inspects content returned by a tool and uses it as evidence to assign a document or entity to a category.",
      "source_description": "A tool observation containing document text or extracted content.",
      "target_description": "An agent classification decision that assigns the observed document or entity to a category."
    },
    {
      "name": "EXTRACTS_FIELD_VALUES_FROM_OBSERVED_CONTENT",
      "definition": "The agent identifies and extracts specific labeled or quantitative field values from content returned by a tool.",
      "source_description": "A tool observation containing document text with embedded field values.",
      "target_description": "An agent decision or result that records extracted field values from the observed content."
    },
    {
      "name": "OBSERVED_CONFLICTING_VALUES_TRIGGER_PRECEDENCE_RULE",
      "definition": "When a tool observation contains multiple candidate values for the same logical field with different amounts, the agent applies a predefined precedence rule to select the correct value.",
      "source_description": "A tool observation containing multiple conflicting candidate values for a requested field.",
      "target_description": "An agent decision that selects one candidate value by applying a precedence or disambiguation rule."
    },
    {
      "name": "PARTIAL_OBSERVATION_TRIGGERS_FOLLOW_UP_INSPECTION",
      "definition": "An observation that provides only partial or insufficient content for a required analysis causes the agent to perform a subsequent action to inspect more complete content.",
      "source_description": "A tool observation that provides only a partial view of the relevant content or indicates missing information.",
      "target_description": "A subsequent agent tool call intended to retrieve additional or full content for the same target."
    },
    {
      "name": "PLAN_IMPLEMENTED_BY_TOOL_CALL",
      "definition": "A plan or intended action described in the agent's reasoning is executed as a tool call.",
      "source_description": "An agent thought or plan describing a next operation to be performed.",
      "target_description": "A tool call that executes the operation described in the plan."
    },
    {
      "name": "UNPROCESSED_ITEMS_PROMPT_FURTHER_INSPECTION",
      "definition": "The agent's analysis or observation identifies items that have not yet been examined or processed, prompting a subsequent tool call to inspect those remaining items.",
      "source_description": "An agent analysis or observation noting that some items remain unexamined or unprocessed.",
      "target_description": "A subsequent tool call that inspects or processes the identified remaining items."
    }
  ]
}

